UPDATE bi_alert_rule SET rule_name = #{ruleName}, threshold = #{threshold}, severity = #{severity},
       enabled = #{enabled}, notify_channel = #{notifyChannel}, notify_targets = #{notifyTargets}, updated_at = #{updatedAt}
WHERE rule_id = #{ruleId} AND tenant_id = #{tenantId}

mapper.select:
SELECT rule_id, tenant_id, rule_name, metric_code, domain, condition_type, threshold, severity, enabled, notify_channel, notify_targets, created_at, updated_at
FROM bi_alert_rule WHERE tenant_id = #{tenantId}
AND domain = #{domain}
ORDER BY created_at DESC

